import {CARDS,TERRAINS,SKILLS,newState,loadState,saveState,createRun,getChoices,selectNode,applyStarter,takeCard,finishFlight,getSupportChoices,resolveSupport,bankRun,buySkill,getModifiers} from './model.mjs';
import {PhoenixFlight} from './flight.mjs';

const app=document.querySelector('#app'),header=document.querySelector('#header');
let state;try{state=loadState(localStorage)}catch{state=newState()}
let screen='home',engine=null,pendingCard=null,replaceIndex=0,lastSnapshot=null,paused=false,boostTimer=null,boostHeld=false,swipeX=0;
let muted=false;try{muted=localStorage.getItem('emberwing-muted')==='true'}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cardList=()=>Object.values(CARDS),skillList=()=>Object.values(SKILLS);
const cardById=id=>CARDS[id]||cardList().find(c=>c.id===id);
const iconPaths={
 flame:'<path d="M12 2c1 6 7 6 7 12a7 7 0 0 1-14 0c0-3 2-5 4-7-1 4 0 6 2 7-2-5 1-8 1-12Z"/><path d="M12 12c0 3 3 3 3 6a3 3 0 0 1-6 0c0-2 2-3 3-6Z"/>',
 wing:'<path d="M3 17 6 6l6 8L21 4l-3 13-6 4-9-4Z"/><path d="m6 6 2 12m13-14-9 17m-9-4 9-3"/>',
 route:'<path d="M6 20V9a4 4 0 0 1 4-4h8M6 14h8a4 4 0 0 1 4 4v2"/><circle cx="6" cy="20" r="2"/><path d="m15 2 3 3-3 3"/><circle cx="18" cy="20" r="2"/>',
 cards:'<rect x="7" y="3" width="13" height="17" rx="2"/><path d="m4 5-2 1 3 16 11-2M13.5 7 16 11l-2.5 4L11 11l2.5-4Z"/>',
 ember:'<path d="m12 2 6 8-6 12-6-12 6-8Z"/><path d="M6 10h12m-6-8v20"/>',
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
 star:'<path d="m12 2 2.7 6.3 6.8.7-5.1 4.5 1.5 6.5-5.9-3.5L6.1 20l1.5-6.5L2.5 9l6.8-.7L12 2Z"/>',
 shield:'<path d="m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 wisp:'<path d="M12 3c-5 4-8 7-8 11a8 8 0 0 0 16 0c0-3-2-6-5-8 1 4-1 6-3 7 1-4 1-7 0-10Z"/><circle cx="10" cy="15" r=".7"/><circle cx="15" cy="15" r=".7"/>',
 wind:'<path d="M3 8h11a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M5 17h6a2 2 0 1 1-2 2"/>',
 leaf:'<path d="M20 3C7 2 2 7 4 15c8 5 16 0 16-12Z"/><path d="M3 21 17 7M8 16l1-7m4 2h5"/>',
 ruins:'<path d="M3 21h18M4 7h16M7 7v14m10-14v14M3 7l9-5 9 5M5 11h4m6 0h4"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 sound:'<path d="m11 4-6 5H2v6h3l6 5V4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 mute:'<path d="m11 4-6 5H2v6h3l6 5V4Zm5 5 5 6m0-6-5 6"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 moon:'<path d="M20.5 14A9 9 0 0 1 10 3a9 9 0 1 0 10.5 11Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>'
};
function icon(name,cls=''){const k=({'✧':'wisp','✦':'sun','◈':'ember','ϟ':'wind','⌄':'wing','⌃':'wing','»':'wind','◇':'shield','♢':'heart','≈':'wind','♨':'flame','♡':'heart',boost:'flame',survival:'shield',collection:'wisp',mobility:'wing',spirit:'wisp',ash:'shield',speed:'wind',phoenix:'flame',rebirth:'sun',control:'wing'}[String(name).toLowerCase()]||name);return `<svg class="ico ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.star}</svg>`}
function terrainInfo(id){const t=TERRAINS[id]||{};return {name:t.name||({ruins:'Ancient Ruins',canopy:'Luminous Canopy',storm:'Storm Spires'}[id]),icon:{ruins:'ruins',canopy:'leaf',storm:'wind'}[id]||'flame'}}
function heartMarkup(hp,max=3){return `<span class="hearts" aria-label="${hp} of ${max} health">${Array.from({length:max},(_,i)=>icon('heart',i<hp?'':'empty')).join('')}</span>`}
function notify(message){const e=document.querySelector('#toast');e.textContent=message;e.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.classList.remove('show'),2800)}
function persist(){try{if(!saveState(state,localStorage)&&!persist.warned){persist.warned=true;notify('Storage is unavailable. Keep this tab open to retain progress.')}}catch{if(!persist.warned){persist.warned=true;notify('Storage is unavailable. Keep this tab open to retain progress.')}}}
function destroyFlight(){if(engine){engine.destroy();engine=null}document.body.classList.remove('playing');clearTimeout(boostTimer)}
function navigate(view){destroyFlight();screen=view;pendingCard=null;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){document.body.dataset.screen=screen;document.body.classList.toggle('playing',screen==='flight');renderHeader();const views={home:renderHome,map:renderMap,cards:renderCards,replace:renderReplace,support:renderSupport,briefing:renderBriefing,skills:renderSkills,codex:renderCodex,result:renderResult};app.innerHTML=(views[screen]||renderHome)();app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');if(screen==='map')drawMap();if(screen==='replace')bindSwipe()}
function goToRun(){if(!state.run){navigate('home');return}let p=state.run.phase;if(p==='flight'){state.run.phase='briefing';p='briefing'}if(p==='ended'){bankRun(state);persist();navigate('result')}else navigate(({starter:'cards',reward:'cards',map:'map',briefing:'briefing',support:'support'}[p])||'map')}
function beginRun(){state.run=createRun(state.profile);persist();goToRun()}
function miniCards(cards){return `<div class="slot-list">${Array.from({length:3},(_,i)=>{const c=cardById(cards[i]);return c?`<div class="mini-card" style="--card:${esc(c.color||'#d9bd83')}">${cardArt(c)}<h4>${esc(c.name)}</h4></div>`:`<div class="mini-card empty"><b>◇</b><h4>Open slot</h4></div>`}).join('')}</div>`}
function runStats(){const r=state.run;return `<div class="run-info">${heartMarkup(r.hp,r.maxHp||3)}<span class="stat">${icon('ember')}${Math.floor(r.embers||0)}</span><span class="pill">Stop ${Math.min(r.step+1,7)} / 7</span></div>`}
function cardMarkup(c,{action='',label='Choose this card',extra=''}={}){return `<${action?'button':'article'} class="game-card" ${action?`data-action="${action}" data-id="${esc(c.id)}"`:''} style="--card:${esc(c.color||'#dfbd83')}"><span class="card-emblem">${cardArt(c)}</span><span class="card-tag">${esc(c.tag||'Phoenix blessing')}</span><h3>${esc(c.name)}</h3><p>${esc(c.detail||c.description)}</p>${extra}${action?`<span class="card-pick">${label}${icon('arrow')}</span>`:''}</${action?'button':'article'}>`}
function renderCards(){const r=state.run,starter=r.phase==='starter';return `<section class="center-view"><div class="eyebrow">${starter?'Every flame begins somewhere':'A gift from the skies'}</div><h1>${starter?'Choose your first spark.':'How will your flight evolve?'}</h1><p class="lead">${starter?'One card starts your strategy. Combine it with new discoveries along the way.':'A new possibility for your three-card build. All effects activate automatically.'}</p>${rewardBanner()}<div class="card-offers">${r.offers.map(id=>cardMarkup(cardById(id),{action:'card'})).join('')}</div>${r.cards.length?`<section class="loadout" style="max-width:480px;margin:25px auto"><div class="loadout-head"><h2 class="side-title" style="margin:0">Your current build</h2><span>${r.cards.length}/3</span></div>${miniCards(r.cards)}</section>`:''}<p class="hint">${r.cards.length>=3?'Your slots are full. You can replace any card or keep your current build.':'Movement changes apply at the next flight. Your cards last for this expedition.'}</p></section>`}
function renderReplace(){const incoming=cardById(pendingCard),old=cardById(state.run.cards[replaceIndex]);return `<section class="center-view"><div class="eyebrow">Three slots. One meaningful choice.</div><h1>Make room for a new spark?</h1><p class="lead">Swipe the equipped card to choose what to replace. Keeping your current build is always an option.</p><div class="replacement" id="replace-swipe">${cardMarkup(old)}<div class="carousel-dots">${state.run.cards.map((_,i)=>`<i class="carousel-dot ${i===replaceIndex?'active':''}"></i>`).join('')}</div><div class="small subtle">Equipped slot ${replaceIndex+1} of 3 · swipe to change</div></div><div class="replace-arrow">↓</div><div class="replace-summary">Replace <strong>${esc(old.name)}</strong> with <strong style="color:var(--gold)">${esc(incoming.name)}</strong></div><p class="lead">${esc(incoming.detail||incoming.description)}</p><div class="two-actions"><button class="secondary" data-action="keep">Keep build · +8 embers</button><button class="primary" data-action="replace">Replace slot ${replaceIndex+1}${icon('arrow')}</button></div></section>`}
function bindSwipe(){const e=document.querySelector('#replace-swipe');e.addEventListener('pointerdown',ev=>swipeX=ev.clientX);e.addEventListener('pointerup',ev=>{const dx=ev.clientX-swipeX;if(Math.abs(dx)>30){replaceIndex=(replaceIndex+(dx<0?1:2))%3;render()}})}
function renderSupport(){const r=state.run,n=r.current,choices=getSupportChoices(r);return `<section class="center-view"><div class="eyebrow">Checkpoint ${r.step+1}</div><div class="support-symbol">${icon(n.kind==='camp'?'sun':'moon')}</div><h1>${esc(n.name)}</h1><p class="lead">${esc(n.description)}</p><div style="display:flex;justify-content:center;margin:20px">${runStats()}</div><div class="support-offers">${choices.map((c,i)=>`<button class="route-choice" data-action="support" data-index="${i}"><span class="card-tag">${i===0?'A path to consider':'Another possibility'}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="choice-detail">${icon(i===0?'heart':'star')}${esc(c.detail||'The choice is yours.')}</div><span class="arrow">${icon('arrow')}</span></button>`).join('')}</div><p class="hint">No timer. Take a breath and choose what your current build needs.</p></section>`}
function modifierText(){const r=state.run,m=getModifiers(r.cards,state.profile.skills),bits=[];if(Math.abs(m.speed-1)>.01)bits.push(`Travel ${m.speed>1?'+':''}${Math.round((m.speed-1)*100)}%`);if(Math.abs(m.flap-1)>.01)bits.push(`Lift ${m.flap>1?'+':''}${Math.round((m.flap-1)*100)}%`);if(Math.abs(m.gravity-1)>.01)bits.push(`Gravity ${m.gravity>1?'+':''}${Math.round((m.gravity-1)*100)}%`);return bits.join(' · ')||'Balanced flight · familiar controls'}
function renderBriefing(){const r=state.run,n=r.current,t=terrainInfo(n.terrain);return `<section class="center-view"><div class="eyebrow">${n.type==='finale'?'The last ascent':`Flight · Stop ${r.step+1}`}</div><h1>The next sky is yours.</h1><p class="lead">${esc(n.description)}</p><div class="briefing-panel"><div class="briefing-copy"><span class="pill ${n.elite?'red':'gold'}">${n.elite?'Elite passage':n.type==='finale'?'Finale':'Ordinary passage'}</span><h2>${esc(n.name)}</h2><p>${esc(t.name)} · ${esc(modifierText())}</p></div></div><div class="brief-stats"><div><small>Passage</small><strong>≈${n.duration||38} seconds</strong></div><div><small>Shared health</small><strong>${r.hp} / ${r.maxHp||3}</strong></div><div><small>Flame vitality</small><strong>${Math.round(r.flame??100)} / 100</strong></div></div><p class="route-readiness">${(r.flame??100)<(n.elite?70:n.passage==='cavern'?60:35)?'Low Flame for this passage. A refuge offers easier refuelling.':'Boost through a fuel window to save wingbeats and reach the exit sooner.'}</p><p class="hint">Optional challenge: ${esc(n.challenge||'Reach the exit without taking damage.')}<br>Wingbeat −${Math.round(7*(n.flameDrain||1))} Flame. Ember +${22+(n.fuelBonus||0)}. Heart ember +${38+(n.fuelBonus||0)}.<br>Glide to conserve effort. Hold Boost to pause.</p><div class="two-actions"><button class="primary" data-action="launch">Take flight ${icon('wing')}</button></div><section class="loadout" style="max-width:480px;margin:25px auto">${miniCards(r.cards)}</section></section>`}
function renderSkills(){const branches=[{name:'Spirit',key:'wisp',icon:'wisp',sub:'Let the little lights find you.'},{name:'Flame',key:'boost',icon:'flame',sub:'A stronger spark. A longer burn.'},{name:'Rebirth',key:'rebirth',icon:'sun',sub:'The end is only an ember.'}];const inRun=state.run&&state.run.phase!=='ended';return `<section class="page-head"><div><div class="eyebrow">Permanent progression</div><h1>From ember to eternity.</h1><p>Grow your phoenix between expeditions.</p></div><span class="pill gold">Ascension tree</span></section><div class="skill-intro"><p>Embers gathered on every expedition become lasting strength. Each branch offers two permanent skills. Your basic wisp and Boost are yours from the very first flight.${inRun?' Finish your expedition to spend embers; skills stay fixed during a run.':''}</p><span class="skill-bank">${icon('ember')}${state.profile.embers||0}</span></div><div class="skill-branches">${branches.map(b=>{const skills=skillList().filter(s=>s.id.startsWith(b.key));return `<section class="skill-branch"><div class="branch-head">${icon(b.icon)}<div><h2>${b.name}</h2><span>${b.sub}</span></div></div>${skills.map(s=>{const owned=!!state.profile.skills[s.id],req=s.requires?Array.isArray(s.requires)?s.requires:[s.requires]:[],locked=req.some(id=>!state.profile.skills[id]);return `<div class="skill-node ${owned?'owned':''}"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p>${owned?`<span class="owned-label">${icon('check')} ASCENDED</span>`:`<button class="${!locked&&!inRun&&state.profile.embers>=s.cost?'primary':'secondary'}" data-action="buy-skill" data-id="${esc(s.id)}" ${locked||inRun||state.profile.embers<s.cost?'disabled':''}>${locked?'Unlock the preceding skill':inRun?'Available between expeditions':`${icon('ember')}${s.cost} embers`}</button>`}</div>`}).join('')}</section>`}).join('')}</div><p class="hint" style="text-align:right;max-width:none;margin-top:22px">Progress stays in this browser. Clearing browser data removes your saved progress.</p>`}
function renderCodex(){return `<section class="page-head"><div><div class="eyebrow">The field guide</div><h1>Twelve sparks. Countless flights.</h1><p>Discover the effects that shape your three-card build.</p></div><span class="pill">12 / 12 discovered</span></section><p class="section-note">Cards activate automatically. Build a collection engine, ride the storms, or protect your flame. Movement bonuses are capped to keep every passage fair. New cards and replacements are chosen safely between flights.</p><div class="codex-grid">${cardList().map(c=>cardMarkup(c)).join('')}</div>`}
function renderResult(){const r=state.run;return `<section class="center-view"><div class="eyebrow">${r.success?'Expedition complete':'Every ember has another story'}</div><div class="result-symbol">${icon(r.success?'sun':'flame')}</div><h1>${r.success?'The sky remembers.':'Your flame will rise again.'}</h1><p class="lead">${r.success?'Seven stops. One phoenix. A path entirely your own.':'Your collected embers are safe. The next route holds another possibility.'}</p><div class="result-stats"><div><strong>${Math.floor(r.embers||0)}</strong><span>Embers banked</span></div><div><strong>${Math.floor(r.score||0)}</strong><span>Run score</span></div><div><strong>${r.success?7:r.step}</strong><span>Stops cleared</span></div></div><div class="result-loadout">${miniCards(r.cards)}</div><p class="result-note">${r.success?'Try a new combination, take the other fork, or turn these embers into lasting strength.':'A different card. A quieter route. A well-timed Boost. There is always another way through.'}</p><div class="two-actions"><button class="secondary" data-action="skills">Ascend your phoenix ${icon('sun')}</button><button class="primary" data-action="begin">Begin again ${icon('arrow')}</button></div><p class="hint">Expedition seed: ${esc(r.seed)} · Progress saved on this device</p></section>`}
function launch(){destroyFlight();screen='flight';paused=false;renderHeader();document.body.classList.add('playing');const r=state.run,n=r.current,t=terrainInfo(n.terrain);app.innerHTML=`<section class="flight-shell"><div class="flight-device"><div class="flight-hud"><div><div class="flight-title">${esc(t.name)} · ${n.type==='finale'?'Finale':r.step+1+'/7'}</div><div id="flight-health">${heartMarkup(r.hp,r.maxHp)}</div></div><div class="flight-topstats"><span>${icon('ember')}<b id="flight-embers">0</b></span><span>${icon('star')}<b id="flight-score">0</b></span></div></div><div class="flame-hud"><span>${icon('flame')} FLAME</span><div id="flame-meter" role="meter" aria-label="Flame vitality" aria-valuemin="0" aria-valuemax="100"><i id="flame-fill"></i></div><b id="flame-value">100</b></div><div class="flight-progress"><i id="flight-progress-bar"></i></div><div class="canvas-wrap"><canvas id="flight-canvas" aria-label="Phoenix flight playfield. Use the Flap and Boost buttons below."></canvas><div class="flight-event" id="flight-event">Wingbeats spend Flame. Seek the embers.</div><div class="flight-mobile-cards">${r.cards.map(id=>`<span>${icon(cardById(id).icon||cardById(id).tag)}</span>`).join('')}</div></div><div class="flight-dock"><span class="dock-label">WINGBEAT −${Math.round(7*(n.flameDrain||1))}<br>EMBER +${22+(n.fuelBonus||0)}<br>HOLD BOOST TO PAUSE</span><button class="flight-control boost-control" id="boost-btn" aria-label="Boost; hold to pause">${icon('flame')}<span id="boost-label" class="cooldown-label">BOOST</span></button><button class="flight-control flap-control" id="flap-btn" aria-label="Flap upward">${icon('wing')}<span id="flap-label">FLAP −7</span></button></div><div id="pause-layer"></div></div><aside class="flight-sidebar"><div class="eyebrow">Your current flight</div><h2>${esc(n.name)}</h2><p>${esc(n.description)}</p><section class="loadout"><h3 class="side-title">Your build</h3>${miniCards(r.cards)}</section><p class="hint">${esc(n.challenge)}<br><br>SPACE / ↑ · Flap<br>B / SHIFT · Boost<br>ESC · Pause<br><br>On mobile, both buttons sit beneath your right thumb. Hold Boost to pause.</p></aside></section>`;const mods=getModifiers(r.cards,r.skills||state.profile.skills);engine=new PhoenixFlight({canvas:document.querySelector('#flight-canvas'),terrain:n.terrain,elite:n.elite,seed:`${r.seed}-${n.id}`,duration:n.duration||38,challengeId:n.challengeId,challengeTarget:n.challengeTarget,cards:r.cards,skills:r.skills||state.profile.skills,modifiers:mods,node:n,hp:r.hp,flame:r.flame??100,maxHp:r.maxHp||mods.maxHp,shield:r.shield||0,rebirthAvailable:!!mods.rebirth&&!r.usedRebirth,assets:{phoenixAtlas:'assets/phoenix-atlas.png',background:'assets/moonlit-valley.png',terrainAtlas:'assets/moon-materials.png'},onUpdate:updateFlight,onFinish:completeFlight,onPause:p=>{if(p&&!paused){paused=true;showPause()}}});if(engine.setMuted)engine.setMuted(muted);bindControls();engine.start()}
function updateFlight(s){lastSnapshot=s;const health=document.querySelector('#flight-health');if(!health)return;health.innerHTML=heartMarkup(Math.max(0,Math.ceil(s.hp)),s.maxHp||state.run.maxHp||3);document.querySelector('#flight-embers').textContent=Math.floor(s.embers||0);document.querySelector('#flight-score').textContent=Math.floor(s.score||0);document.querySelector('#flight-progress-bar').style.width=`${Math.min(100,(s.progress||0)*100)}%`;const boost=document.querySelector('#boost-btn'),cool=s.boostCooldown||0;boost.classList.toggle('cooling',cool>.05);document.querySelector('#boost-label').textContent=cool>.05?`${cool.toFixed(1)}s`:'BOOST';const vitality=Math.round(s.flame??100),meter=document.querySelector('#flame-meter');meter.setAttribute('aria-valuenow',String(vitality));document.querySelector('#flame-fill').style.transform=`scaleX(${vitality/100})`;document.querySelector('#flame-value').textContent=vitality;const exhausted=s.canFlap===false;document.querySelector('.flight-device').classList.toggle('low-flame',vitality<=21);document.querySelector('.flight-device').classList.toggle('exhausted',exhausted);const flap=document.querySelector('#flap-btn');flap.setAttribute('aria-disabled',String(exhausted));flap.setAttribute('aria-label',exhausted?'Exhausted. Collect an ember to flap again.':`Flap upward. Costs ${s.flapCost||7} Flame.`);document.querySelector('#flap-label').textContent=exhausted?'GLIDE':`FLAP −${s.flapCost||7}`;document.querySelector('#flight-event').textContent=s.event||(exhausted?'Flame exhausted · glide toward an ember':vitality<=21?'Flame fading · seek an ember':'Glide between wingbeats. Embers restore Flame.')}
function completeFlight(result){const current=engine;engine=null;current?.destroy();finishFlight(state.run,result);persist();if(state.run.phase==='ended'){bankRun(state);persist()}goToRun()}
function bindControls(){const flap=document.querySelector('#flap-btn'),boost=document.querySelector('#boost-btn');flap.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.flap()});boost.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.boost()});flap.addEventListener('pointerdown',e=>{e.preventDefault();if(engine&&!paused)engine.flap()});boost.addEventListener('pointerdown',e=>{e.preventDefault();boost.setPointerCapture(e.pointerId);boostHeld=false;boostTimer=setTimeout(()=>{boostHeld=true;togglePause()},480)});boost.addEventListener('pointerup',e=>{e.preventDefault();clearTimeout(boostTimer);if(!boostHeld&&engine&&!paused)engine.boost()});boost.addEventListener('pointercancel',()=>clearTimeout(boostTimer));document.querySelector('.canvas-wrap').addEventListener('pointerdown',e=>{e.preventDefault();if(!paused)engine?.flap()})}
function showPause(){const e=document.querySelector('#pause-layer');if(!e)return;e.innerHTML=`<div class="pause-overlay"><div class="support-symbol">${icon('pause')}</div><h2>A moment of stillness.</h2><p>Your flight is safe. Resume when you are ready.</p><button class="primary" data-action="resume">Return to the skies ${icon('arrow')}</button><button class="secondary" data-action="leave-flight">Return to camp</button><p class="hint">Returning to camp restarts this passage from its saved checkpoint.</p></div>`}
function togglePause(){if(!engine)return;if(paused){paused=false;document.querySelector('#pause-layer').innerHTML='';engine.resume()}else{paused=true;engine.pause();showPause()}}
function acceptCard(id,slot=null){const r=state.run;if(r.phase==='starter')applyStarter(r,id);else takeCard(r,id,slot);pendingCard=null;persist();goToRun()}
function keepBuild(){const r=state.run;/* takeCard with a current card resolves a reward without changing slots. */if(typeof takeCard==='function')takeCard(r,null);persist();goToRun()}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const action=btn.dataset.action,id=btn.dataset.id;switch(action){case'home':navigate('home');break;case'play':state.run&&state.run.phase!=='ended'?goToRun():navigate('home');break;case'continue':goToRun();break;case'begin':beginRun();break;case'restart':if(state.run&&state.run.phase!=='ended'){state.run.phase='ended';state.run.success=false;bankRun(state)}persist();beginRun();break;case'skills':navigate('skills');break;case'codex':navigate('codex');break;case'mute':muted=!muted;try{localStorage.setItem('emberwing-muted',String(muted))}catch{}engine?.setMuted?.(muted);renderHeader();notify(muted?'Sound muted':'Sound enabled');break;case'back-route':if(['briefing','support'].includes(state.run?.phase)){state.run.path.pop();state.run.current=null;state.run.phase='map';persist();goToRun()}else navigate('home');break;case'node':selectNode(state.run,id);persist();goToRun();break;case'card':if(state.run.cards.length>=3){pendingCard=id;replaceIndex=0;screen='replace';render();window.scrollTo({top:0,behavior:'instant'})}else acceptCard(id);break;case'replace':acceptCard(pendingCard,replaceIndex);break;case'keep':keepBuild();break;case'support':resolveSupport(state.run,Number(btn.dataset.index));persist();goToRun();break;case'launch':launch();break;case'buy-skill':if(buySkill(state.profile,id)){persist();const y=window.scrollY;render();window.scrollTo(0,y);notify('Your phoenix has ascended.')}break;case'resume':togglePause();break;case'leave-flight':destroyFlight();navigate('home');break}});
document.addEventListener('keydown',e=>{if(screen==='flight'&&engine){if(['Space','ArrowUp','KeyB','ShiftLeft','ShiftRight','Escape'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape')togglePause();else if(!paused&&['Space','ArrowUp'].includes(e.code))engine.flap();else if(!paused&&['KeyB','ShiftLeft','ShiftRight'].includes(e.code))engine.boost()}else if(screen==='replace'&&['ArrowLeft','ArrowRight'].includes(e.code)){replaceIndex=(replaceIndex+(e.code==='ArrowRight'?1:2))%3;render()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('orientationchange',()=>{if(engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('pagehide',persist);
function renderHeader(){const r=state.run,active=r&&r.phase!=='ended',isHome=screen==='home';header.innerHTML=`<div class="game-top-left"><button class="game-round" data-action="${['briefing','support'].includes(screen)?'back-route':'home'}" aria-label="${['briefing','support'].includes(screen)?'Back to map':'Return to camp'}">${icon(isHome?'flame':'arrow')}</button>${!isHome?`<span class="game-screen-label">${screen==='skills'?'ASCENSION':screen==='codex'?'GRIMOIRE':screen==='map'?'THE SHATTERED SKIES':'EMBERWING'}</span>`:''}</div><div class="header-end"><span class="bank" title="${active?'Expedition':'Banked'} embers">${icon('ember')}<span>${Math.floor(active?r.embers:state.profile.embers)||0}</span></span><button class="game-round" data-action="mute" aria-label="${muted?'Enable':'Mute'} sound">${icon(muted?'mute':'sound')}</button></div>`}
function renderHome(){const active=state.run&&state.run.phase!=='ended';return `<section class="game-splash"><div class="splash-scenery"></div><div class="splash-phoenix" role="img" aria-label="Golden phoenix soaring over the floating kingdoms"></div><div class="sparks">${Array.from({length:22},(_,i)=>`<i style="--x:${8+i*4}%;--t:${4+i%5}s;--d:${-i*.6}s"></i>`).join('')}</div><div class="game-title"><div class="title-ornament">✦ ━━━━━ ◇ ━━━━━ ✦</div><h1>EMBERWING</h1><div class="game-subtitle">RISE FROM THE ASHES</div><div class="title-ornament bottom">◇</div></div><div class="game-home-bottom"><div class="home-run-label">${active?`EXPEDITION IN PROGRESS · STOP ${state.run.step+1}/7`:'A NEW SKY. A DIFFERENT FLAME.'}</div><button class="game-play" data-action="${active?'continue':'begin'}"><span class="play-glyph">${icon('wing')}</span><span>${active?'CONTINUE':'TAKE FLIGHT'}<small>${active?'Your journey awaits':'Begin an expedition'}</small></span>${icon('arrow')}</button><div class="game-menu-tools"><button data-action="skills"><span class="menu-medallion map-art-5"></span><span>Ascension</span></button><button data-action="codex"><span class="menu-medallion map-art-4"></span><span>Grimoire</span></button><div class="game-record"><b>${state.profile.stats?.wins||0}</b><span>ASCENTS</span></div></div>${active?`<button class="new-expedition" data-action="restart">NEW EXPEDITION<small>Bank this run and start fresh</small></button>`:''}<div class="game-save-note">${state.profile.stats?.completedRuns||0} expeditions · saved on this device</div></div></section>`}
function renderMap(){
  const r=state.run,choices=getChoices(r);
  const nodeLookup=new Map(r.map.flat().map(n=>[n.id,n]));
  const supportAhead=node=>{let frontier=[node];for(let depth=0;depth<4;depth++){const found=frontier.filter(n=>n!==node&&n.type==='support');if(found.length)return [...new Set(found.map(n=>n.kind==='camp'?'Sanctuary':n.kind==='shrine'?'Flame shrine':'Moon event'))].join(' / ');frontier=frontier.flatMap(n=>(n.nextIds||[]).map(id=>nodeLookup.get(id)).filter(Boolean));}return 'The Phoenix Gate';};
  const artwork=n=>n.type==='support'?(n.kind==='camp'?3:n.kind==='fuelshrine'?4:4):n.type==='finale'?5:({ruins:0,canopy:1,storm:2}[n.terrain]??0);
  const routeTitle=n=>n.type==='support'?(n.kind==='camp'?'Sanctuary':n.kind==='shrine'?'Flame shrine':'Moonlit encounter'):n.type==='finale'?'The final ascent':({refuge:'Gentle passage',cavern:'Hidden passage',gauntlet:'Elite trial'}[n.routeStyle]||(n.elite?'Elite trial':'Open passage'));
  return `<section class="game-map-screen map-v2">
    <div class="map-titlebar"><div><span class="map-chapter">EXPEDITION · ${Math.min(r.step+1,7)} OF 7</span><h1>The Shattered Skies</h1><p>SCOUT AHEAD. CHOOSE YOUR OWN ASCENT.</p></div><div class="map-vitals">${heartMarkup(r.hp,r.maxHp||3)}<span>${icon('flame')}<b>${Math.round(r.flame??100)}</b><small>FLAME</small></span></div></div>
    <div class="map-atlas-frame"><div class="map-atlas-legend"><span><i class="legend-taken"></i>Your path</span><span><i class="legend-open"></i>Open route</span><span><i class="legend-locked"></i>Unexplored</span></div><div class="game-map-viewport" id="map-viewport"><svg id="journey-map" class="game-world-map" viewBox="0 0 390 1240" role="group" aria-label="Branching expedition map. Scroll to scout future locations. The glowing destinations can be inspected before travel."></svg></div><span class="map-scroll-cue">SCROLL TO SCOUT THE SKY ${icon('wing')}</span></div>
    <div class="map-crossroads"><div class="map-crossroads-heading"><span>${choices.length>1?'YOUR NEXT CROSSROADS':'THE PATH AHEAD'}</span><small>Tap to inspect · travel afterward</small></div><div class="map-route-options">${choices.map((n,index)=>{
      const art=artwork(n),style=n.routeStyle||(n.type==='support'?'support':n.elite?'gauntlet':'refuge');
      const fuel=n.fuelPreview||(n.type==='support'?'A safe stop between flights':n.fuelCadence?`Wisp trails every ${n.fuelCadence}s`:'Steady wisp trails');
      const risk=n.riskPreview||(n.type==='support'?'Choose your boon':n.elite?'Tighter paths · richer rewards':n.type==='finale'?'The final challenge':'Room to glide');
      const reward=n.type==='support'?(n.reward||'A boon for your build'):`${n.bonusEmbers||0} embers · ${n.draftTheme||'New'} cards`;
      const budget=n.type==='support'?`<span>${icon('flame')}${esc(fuel)}</span>`:`<span>${icon('wing')}−${Math.round(7*(n.flameDrain||1))}</span><span>${icon('wisp')}+${22+(n.fuelBonus||0)}</span><span>${icon('ember')}×${Number(n.routeReward||1).toFixed(2)}</span><small>Flap / wisp / loot</small>`;
      const routeRisk=n.type==='support'?risk:`${n.passage==='cavern'?'Tight cavern':n.elite?'Elite hazards':'Open sky'} · ${n.fuelCadence<=2?'frequent fuel':n.fuelCadence>=4?'lean fuel':'spaced fuel'}`;
      return `<button class="map-route-preview route-${esc(style)}" data-action="node" data-id="${esc(n.id)}" aria-label="Inspect ${esc(n.name)}. ${esc(fuel)}. ${esc(risk)}. ${esc(reward)}"><span class="map-route-illustration" style="background-position:${art%3*50}% ${Math.floor(art/3)*100}%" aria-hidden="true"></span><span class="map-route-copy"><span class="map-route-eyebrow">${esc(routeTitle(n))}<span>${n.type==='support'?'CHECKPOINT':`${n.duration||38}s`}</span></span><strong>${esc(n.name)}</strong><span class="map-route-budget">${budget}</span><span class="map-route-risk">${esc(routeRisk)}</span><span class="map-route-reward">${icon(n.type==='support'?'star':'cards')}${esc(reward)}</span><span class="map-route-ahead">Ahead: ${esc(supportAhead(n))}</span></span><span class="map-route-inspect" aria-hidden="true">${icon('arrow')}</span></button>`;
    }).join('')}</div></div>
    <div class="map-build-dock"><div class="map-dock-heading"><span>YOUR THREE SPARKS</span><span>${Math.floor(r.embers||0)} EMBERS GATHERED</span></div>${miniCards(r.cards)}</div>
  </section>`;
}

function drawMap(){
  const r=state.run,svg=document.querySelector('#journey-map');if(!svg)return;
  const choices=getChoices(r),available=new Set(choices.map(n=>n.id)),visited=new Set(r.path),positions={},byId=new Map(r.map.flat().map(n=>[n.id,n]));
  const modern=r.map.some(row=>row.some(n=>Array.isArray(n.nextIds)));
  r.map.forEach((row,i)=>row.forEach((n,j)=>{const lane=modern?(Number.isInteger(n.lane)?n.lane:j):(row.length===2?j*2:1);positions[n.id]={x:[65,195,325][lane]??195,y:1085-i*145};}));
  const nextNodes=n=>Array.isArray(n.nextIds)?n.nextIds.map(id=>byId.get(id)).filter(Boolean):(r.map[n.row+1]||[]);
  const future=new Set(available),queue=[...choices];while(queue.length){for(const n of nextNodes(queue.shift()))if(!future.has(n.id)){future.add(n.id);queue.push(n);}}
  const takenEdges=new Set(r.path.slice(1).map((id,i)=>`${r.path[i]}|${id}`)),last=r.path.at(-1);
  let paths='',locations='',decorations='',clips='';
  const pathMarkup=(d,taken,open,locked,id)=>`<g class="map-route-line ${taken?'path-taken':open?'path-open':locked?'path-locked':'path-future'}"><path d="${d}" class="route-shadow"/><path id="${id}" d="${d}" class="route-thread"/>${open?`<path d="${d}" class="route-current"/>`:''}</g>`;
  r.map.forEach(row=>row.forEach(a=>{for(const b of nextNodes(a)){const p=positions[a.id],q=positions[b.id];if(!p||!q)continue;const d=`M${p.x} ${p.y-33} C${p.x} ${p.y-79},${q.x} ${q.y+81},${q.x} ${q.y+34}`;paths+=pathMarkup(d,takenEdges.has(`${a.id}|${b.id}`),a.id===last&&available.has(b.id),!future.has(a.id)||!future.has(b.id),`route-${a.id}-${b.id}`);}}));
  const starts=(Array.isArray(r.startNodeIds)?r.startNodeIds:r.map[0].map(n=>n.id)).map(id=>byId.get(id)).filter(Boolean);
  for(const node of starts){const q=positions[node.id],d=`M195 1183 C195 1144,${q.x} 1150,${q.x} ${q.y+34}`;paths+=pathMarkup(d,r.path[0]===node.id,r.path.length===0&&available.has(node.id),r.path.length>0&&r.path[0]!==node.id,`origin-${node.id}`);}
  for(let i=0;i<66;i++){const x=(i*137+41)%390,y=(i*211+73)%1240;decorations+=`<circle cx="${x}" cy="${y}" r="${i%5===0?1.6:.7}" fill="#f5dcad" opacity="${.16+(i%4)*.07}"/>`;}
  for(let i=0;i<9;i++){const x=i%2?320:42,y=170+i*119;decorations+=`<g opacity=".17" transform="translate(${x},${y}) rotate(${i%2?-9:8})"><path d="M-53 8Q-37-12-15-6L8-19 40-7 55 15 26 34-4 47-28 29Z" fill="url(#mapIsland)"/><path d="M-38 5Q-10-14 33-2" fill="none" stroke="#b8c692" stroke-width="2"/><path d="M-17-8v-29h8v26m20-1v-24h7v27m-42-23q23-23 48 0" fill="none" stroke="#94b39f" stroke-width="5"/></g>`;}
  r.map.forEach((row,i)=>row.forEach(n=>{
    const p=positions[n.id],reach=available.has(n.id),taken=visited.has(n.id),bypassed=i<r.step&&!taken,possible=future.has(n.id);
    const art=n.type==='support'?(n.kind==='camp'?3:4):n.type==='finale'?5:({ruins:0,canopy:1,storm:2}[n.terrain]??0);
    const label=n.type==='support'?(n.kind==='camp'?'Sanctuary':n.kind==='shrine'?'Flame shrine':'Moon shrine'):n.type==='finale'?'Phoenix Gate':({ruins:'Ancient Ruins',canopy:'Luminous Canopy',storm:'Storm Spires'}[n.terrain]);
    const route=n.type==='support'?(n.kind==='camp'?'REST & RESTORE':n.kind==='shrine'?'FLAME & BOONS':'EVENT & CHOICE'):n.type==='finale'?'THE FINAL ASCENT':({refuge:'GENTLE PASSAGE',cavern:'HIDDEN CAVERN',gauntlet:'ELITE GAUNTLET'}[n.routeStyle]||(n.elite?'ELITE TRIAL':'FLIGHT & CARD'));
    const clip=`map-clip-${n.id}`;clips+=`<clipPath id="${clip}"><circle cx="${p.x}" cy="${p.y}" r="31.5"/></clipPath>`;
    locations+=`<g class="world-map-node ${reach?'reachable':''} ${taken?'taken':''} ${bypassed?'bypassed':''} ${!possible&&!taken?'unreachable':''}" ${reach?`data-action="node" data-id="${esc(n.id)}" role="button" tabindex="0" aria-label="Inspect ${esc(n.name)}. ${esc(n.fuelPreview||n.description)}. ${esc(n.reward)}"`:''}>
      <ellipse cx="${p.x}" cy="${p.y+35}" rx="39" ry="10" fill="#05171e" opacity=".5"/>
      ${reach?`<circle class="node-aureole" cx="${p.x}" cy="${p.y}" r="48" fill="url(#nodeRadiance)"/><circle class="node-pulse" cx="${p.x}" cy="${p.y}" r="38" fill="none" stroke="#ffe6ac" stroke-width="1.5"/><circle cx="${p.x}" cy="${p.y}" r="43" fill="none" stroke="#d9be7c" stroke-opacity=".28"/>`:''}
      <circle cx="${p.x}" cy="${p.y}" r="34" fill="#102e34" stroke="${reach||taken?'#e7c17c':'#6b998b'}" stroke-width="${reach?2:1}"/>
      <g clip-path="url(#${clip})"><svg x="${p.x-32}" y="${p.y-32}" width="64" height="64" viewBox="${art%3*512} ${Math.floor(art/3)*512} 512 512"><image href="assets/map-icons.png" width="1536" height="1024"/></svg></g>
      ${taken?`<circle cx="${p.x+24}" cy="${p.y+24}" r="10" fill="#e3ba73" stroke="#193f3b" stroke-width="2"/><path d="m${p.x+19} ${p.y+24} 3 3 7-7" fill="none" stroke="#173b35" stroke-width="1.8"/>`:''}
      ${n.elite?`<path d="m${p.x+25} ${p.y-38} 9 10-9 10-9-10Z" fill="#a5563f" stroke="#f3ce91"/><path d="m${p.x+25} ${p.y-34} 0 7m0 3v1" stroke="#ffe7bd" stroke-width="1.5"/>`:''}
      <text x="${p.x}" y="${p.y+56}" class="map-node-name" text-anchor="middle">${esc(label)}</text><text x="${p.x}" y="${p.y+73}" class="map-node-kind" text-anchor="middle">${route}</text>
      ${last===n.id?`<g transform="translate(${p.x},${p.y-52})"><path d="M0-7 5 0 0 8-5 0Z" fill="#ffe1a2"/><circle r="11" fill="none" stroke="#e8c37b" stroke-opacity=".35"/></g>`:''}
    </g>`;
  }));
  svg.innerHTML=`<defs><linearGradient id="atlasSky" x2="0" y2="1"><stop stop-color="#102a3b"/><stop offset=".46" stop-color="#173c3e"/><stop offset="1" stop-color="#0b2930"/></linearGradient><radialGradient id="moonRadiance"><stop stop-color="#e9dbac" stop-opacity=".30"/><stop offset=".35" stop-color="#c1d9c0" stop-opacity=".10"/><stop offset="1" stop-color="#a6d8c9" stop-opacity="0"/></radialGradient><radialGradient id="nodeRadiance"><stop stop-color="#f5cd81" stop-opacity=".27"/><stop offset=".63" stop-color="#f5cd81" stop-opacity=".10"/><stop offset="1" stop-color="#f5cd81" stop-opacity="0"/></radialGradient><linearGradient id="mapIsland" x2=".4" y2="1"><stop stop-color="#7f9d85"/><stop offset="1" stop-color="#173544"/></linearGradient><pattern id="atlasContour" width="195" height="220" patternUnits="userSpaceOnUse"><path d="M-30 80Q27 12 107 75T235 72M-30 95Q27 27 107 90T235 87M-30 112Q27 44 107 107T235 104" stroke="#a2bc9d" stroke-opacity=".05" fill="none"/></pattern>${clips}</defs><rect width="390" height="1240" fill="url(#atlasSky)"/><image href="assets/moonlit-valley.png" x="0" y="0" width="390" height="1240" opacity=".18" preserveAspectRatio="xMidYMid slice"/><rect width="390" height="1240" fill="url(#atlasContour)"/><circle cx="195" cy="90" r="155" fill="url(#moonRadiance)"/><circle cx="195" cy="88" r="26" fill="#e9d8a5" opacity=".72"/><circle cx="205" cy="80" r="24" fill="#193641"/><path d="M24 64Q195 8 366 64M24 1222Q195 1264 366 1222" stroke="#9eae8866" stroke-width="1" fill="none"/>${decorations}${paths}${locations}<g transform="translate(195,1183)"><circle r="23" fill="url(#nodeRadiance)"/><path d="M0-13C3-5 12-3 9 6 6 17-10 16-10 5-10 1-7-2-4-6-5 1-1 2 0-13Z" fill="#e9be77"/><circle r="24" fill="none" stroke="#b79d6855"/></g><text x="195" y="36" class="map-gate-title" text-anchor="middle">THE PHOENIX GATE</text><text x="195" y="1223" class="map-origin-label" text-anchor="middle">EVERY FLAME CHOOSES ITS OWN PATH</text>`;
  const viewport=document.querySelector('#map-viewport'),target=positions[choices[0]?.id];
  if(viewport&&target){const ratio=svg.getBoundingClientRect().width/390;viewport.scrollTop=Math.max(0,target.y*ratio-viewport.clientHeight*.62);}
}

function rewardBanner(){const r=state.run,f=r?.lastFlight;if(r?.phase!=='reward'||r.current?.type==='support'||!f)return '';return `<div class="reward-banner">${icon('check')} PASSAGE CLEARED <span>+${f.completionBonus} EMBERS${f.challengeBonus?` · CHALLENGE +${f.challengeBonus}`:''}</span><span>FLAME ${Math.round(r.flame??100)} / 100${f.recoveredFlame?` · CAUGHT YOUR BREATH +${Math.round(f.recoveredFlame)}`:''}</span></div>`}
function cardArt(c){const index=cardList().findIndex(item=>item.id===c.id),col=index%4,row=Math.floor(index/4);return `<span class="illustrated-card-icon" style="background-position:${col*100/3}% ${row*50}%" aria-hidden="true"></span>`}
document.addEventListener('keydown',e=>{const target=e.target.closest?.('.world-map-node[role="button"]');if(target&&['Enter',' '].includes(e.key)){e.preventDefault();selectNode(state.run,target.dataset.id);persist();goToRun()}});
render();
